package br.com.sistemacardapio.promocao;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;import br.com.sistemacardapio.catalogo.Produto;import br.com.sistemacardapio.empresa.Empresa;import jakarta.persistence.*;
@Entity@Table(name="promocao")public class Promocao{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="empresa_id")private Empresa empresa;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="produto_id")private Produto produto;@Column(name="preco_promocional",nullable=false,precision=12,scale=2)private BigDecimal precoPromocional;@Column(nullable=false,length=30)private String tag;@Column(nullable=false)private Instant inicio;@Column(nullable=false)private Instant fim;@Column(nullable=false)private boolean ativa;protected Promocao(){}public Promocao(Produto p,BigDecimal preco,String tag,Instant inicio,Instant fim){id=UUID.randomUUID();empresa=p.getEmpresa();produto=p;atualizar(preco,tag,inicio,fim,true);}public void atualizar(BigDecimal p,String t,Instant i,Instant f,boolean a){precoPromocional=p;tag=t.trim();inicio=i;fim=f;ativa=a;}public UUID getId(){return id;}public Produto getProduto(){return produto;}public BigDecimal getPrecoPromocional(){return precoPromocional;}public String getTag(){return tag;}public Instant getInicio(){return inicio;}public Instant getFim(){return fim;}public boolean isAtiva(){return ativa;}}
